	/**
	 * Default Constructor
	 */
    public OperatorService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new OperatorEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(OperatorRepository.class) );
		this.validator		= applicationContext.getBean(OperatorValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Operator
	 */
		public Operator createOperator( CreateOperatorCommand command ) {

		Operator entity = new Operator();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setOperatorId( command.getOperatorId() );
            entity.setName( command.getName() );
            entity.setIcaoDesignator( command.getIcaoDesignator() );
            entity.setOperatorType( command.getOperatorType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Operator {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateOperatorCommand
	 * @return		Operator
	 */
	public Operator updateOperator( UpdateOperatorCommand command ) {

		Operator entity = new Operator();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setOperatorId( command.getOperatorId() );
            entity.setName( command.getName() );
            entity.setIcaoDesignator( command.getIcaoDesignator() );
            entity.setAircraftOrders( command.getAircraftOrders() );
            entity.setOperatedAircraft( command.getOperatedAircraft() );
            entity.setSalesRegion( command.getSalesRegion() );
            entity.setOperatorType( command.getOperatorType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Operator {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteOperatorCommand
	 */
	public void delete( DeleteOperatorCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getOperatorId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Operator {0} ", id );

	}

	/**
	 * Method to retrieve the Operator via OperatorFetchOneSummary
	 * @param 	summary OperatorFetchOneSummary
	 * @return 	OperatorFetchOneResponse
	 */
	public Operator getOperator( OperatorFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "OperatorFetchOneSummary arg cannot be null" );

		Operator entity = null;
		UUID id = summary.getOperatorId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Operator using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Operators
	 *
	 * @return 	List<Operator>
	 */
    public List<Operator> getAllOperator() {
		List<Operator> list = projector.findAll( new FindAllOperatorQuery() );
		return list;
	}

	/**
	 * assign SalesRegion on Operator
	 * @param		command AssignSalesRegionToOperatorCommand
	 */
	public void assignSalesRegion( AssignSalesRegionToOperatorCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignSalesRegion(command.getOperatorId(), command.getAssignment());

	}

	/**
	 * unAssign SalesRegion on Operator
	 * @param		command UnAssignSalesRegionFromOperatorCommand
	 */
	public void unAssignSalesRegion( UnAssignSalesRegionFromOperatorCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignSalesRegion(command.getOperatorId());
	}
	

